<script setup lang="ts">
import type { MapLocation, WorldRecord } from '~/utils/geography/types'
const emit=defineEmits<{locate:[location:MapLocation]}>()
const {data:records,status,error,refresh}=await useFetch<WorldRecord[]>('/data/geography/records-v1.json',{server:false,default:()=>[]})
const kind=ref('all'),limit=ref(6)
const categories=[['all','Բոլորը'],['mountain','Լեռներ'],['water','Ջրային աշխարհ'],['land','Ցամաք'],['nature','Բնություն'],['country','Պետություններ']]
const filtered=computed(()=>records.value.filter(r=>kind.value==='all'||r.kind===kind.value))
watch(kind,()=>{limit.value=6})
</script>
<template><section id="globe-records" class="geo-section" aria-labelledby="geo-records-title"><header><p class="geo-kicker">ՄՈԼՈՐԱԿԻ ԾԱՅՐԱՀԵՂՈՒԹՅՈՒՆՆԵՐԸ</p><h2 id="geo-records-title">Աշխարհի ռեկորդներ</h2><p>Յուրաքանչյուր ռեկորդ ունի իր չափանիշը։ «Ամենաբարձրը», «ամենամեծը» և «ամենախորը» տարբեր հարցերի պատասխաններ են։</p></header><div class="geo-filters" role="group" aria-label="Ռեկորդների կատեգորիաներ"><button v-for="c in categories" :key="c[0]" class="geo-button" :aria-pressed="kind===c[0]" @click="kind=c[0]!">{{c[1]}}</button></div><p v-if="status==='pending'" role="status">Բեռնում ենք ռեկորդները…</p><p v-if="error" role="alert">Տվյալները չբեռնվեցին։ <button class="geo-button" @click="refresh()">Կրկին փորձել</button></p><p class="geo-note" role="status">{{Math.min(limit,filtered.length)}} / {{filtered.length}} ռեկորդ</p><div class="geo-grid"><article v-for="r in filtered.slice(0,limit)" :id="r.id" :key="r.id" class="panel geo-card"><p class="geo-kicker">{{r.location}}</p><h3>{{r.title}}</h3><p class="geo-value">{{r.measure}}</p><details><summary>Իմանալ ավելին</summary><p>{{r.detail}}</p><p class="geo-note">Նշիչը ներկայացնում է օբյեկտի մոտավոր դիրքը․ տարածական օբյեկտի ամբողջ սահմանը չէ։</p><a class="geo-source" :href="r.source.url" target="_blank" rel="noopener noreferrer">{{r.source.name}} ↗</a></details><div class="geo-actions"><button v-if="r.coordinates" class="geo-button" @click="emit('locate',{coordinates:r.coordinates,label:r.measure})">Ցույց տալ երկրագնդի վրա ↗</button></div></article></div><div v-if="limit<filtered.length" class="geo-actions"><button class="geo-button" @click="limit+=6">Հաջորդ 6 ռեկորդները ↓</button></div></section></template>
